"use client";

import { FormEvent, useEffect, useMemo, useState } from "react";
import "./superadmin.css";
import "./site-catalog.css";
import "./staff.css";
import { createClientSupabase } from "@/lib/supabase/client";
import {siteTemplates} from "@/lib/site-templates/catalog";

type Owner = { id: string; name: string; email: string } | null;
type Implementation = { id: string; name: string; slug: string; plan: string; template_key: string; implementation_template_id:string|null; implementation_status: string; settings: { modules?: string[] }; created_at: string; owner: Owner };
type TemplateConfiguration = { modules?:string[]; tenant_settings?:Record<string,unknown>; branding?:Record<string,unknown>; assistant?:Record<string,unknown>; knowledge?:unknown[]; automations?:unknown[]; company_profile?:Record<string,unknown>; pipeline?:Record<string,unknown>; custom_fields?:unknown[]; catalog?:unknown[]; quick_replies?:unknown[]; notifications?:Record<string,unknown> };
type ImplementationTemplate = { id:string; key:string; name:string; description:string; business_type:string; configuration:TemplateConfiguration; source_tenant_id:string|null; is_system:boolean; current_version?:number; created_at:string };
type SiteProject = { id:string; tenant_id:string; template_key:string; name:string; slug:string; status:string; updated_at:string; published_url?:string|null; deployment_status?:string|null; tenant:{id:string;name:string}|null };
type PlatformStaff={user_id:string;email:string;role:string;active:boolean;tenant_ids:string[]};
type Customization={id:string;tenant_id:string;template_id:string;template_version:number;status:"draft"|"review"|"approved"|"applied"|"rejected";overrides:TemplateConfiguration;review_note:string;updated_at:string;tenant?:{id:string;name:string}|null;template?:{id:string;name:string;current_version:number}|null};

const moduleOptions = [
  ["dashboard","Inicio"],["conversations","Conversaciones"],["contacts","Contactos"],["pipeline","Pipeline"],
  ["tasks","Tareas"],["team","Equipo"],["automations","Automatizaciones"],["reports","Reportes"],
  ["assistant","Asistente IA"],["widget","Chatbox"],["properties","Propiedades"],["inquiries","Interesados"],
  ["visits","Visitas"],["reservations","Reservaciones"],["orders","Pedidos"],["appointments","Citas"],
  ["quotes","Cotizaciones"],["products","Productos"]
];

const statusLabels: Record<string, string> = { draft:"Borrador", configuring:"Configuración", testing:"Pruebas", ready:"Lista para entregar", production:"Producción", suspended:"Suspendida", archived:"Archivada" };

export default function SuperadminPage() {
  const [items, setItems] = useState<Implementation[]>([]);
  const [templates, setTemplates] = useState<ImplementationTemplate[]>([]);
  const [sites, setSites] = useState<SiteProject[]>([]);
  const [section, setSection] = useState<"companies"|"templates"|"customizations"|"sites"|"team">("companies");
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [loggingOut, setLoggingOut] = useState(false);
  const [showForm, setShowForm] = useState(false);
  const [showCloneForm, setShowCloneForm] = useState(false);
  const [editingTemplate, setEditingTemplate] = useState<ImplementationTemplate|null>(null);
  const [showApplyForm, setShowApplyForm] = useState(false);
  const [applyTemplate, setApplyTemplate] = useState<ImplementationTemplate|null>(null);
  const [applyTenantId, setApplyTenantId] = useState("");
  const [applyReplace, setApplyReplace] = useState(false);
  const [preview, setPreview] = useState<{sections:Array<{label:string;incoming:number;current:number;changed:boolean;detail?:string[]}>;warning:string}|null>(null);
  const [versions, setVersions] = useState<Array<{id:string;version:number;name:string;description:string;business_type:string;configuration:TemplateConfiguration;change_summary:string;created_at:string}>>([]);
  const [editorDraft, setEditorDraft] = useState<{name:string;description:string;business_type:string;configuration:TemplateConfiguration}>({name:"",description:"",business_type:"generic",configuration:{}});
  const [editorError, setEditorError] = useState("");
  const [editorRaw, setEditorRaw] = useState<Record<string,string>>({});
  const [customizations, setCustomizations] = useState<Customization[]>([]);
  const [reviewingCustomization, setReviewingCustomization] = useState<Customization|null>(null);
  const [showCustomizationForm, setShowCustomizationForm] = useState(false);
  const [customizationTemplate, setCustomizationTemplate] = useState<ImplementationTemplate|null>(null);
  const [customizationTenantId, setCustomizationTenantId] = useState("");
  const [customizationId, setCustomizationId] = useState<string|null>(null);
  const [customizationDraft, setCustomizationDraft] = useState<TemplateConfiguration>({});
  const [customizationRaw, setCustomizationRaw] = useState<Record<string,string>>({});
  const [customizationError, setCustomizationError] = useState("");
  const [query, setQuery] = useState("");
  const [notice, setNotice] = useState<{ kind:"success"|"error"; text:string } | null>(null);
  const [formError, setFormError] = useState("");
  const [statusSaving, setStatusSaving] = useState<string | null>(null);
  const [name, setName] = useState("");
  const [ownerName, setOwnerName] = useState("");
  const [ownerEmail, setOwnerEmail] = useState("");
  const [templateId, setTemplateId] = useState("");
  const [modules, setModules] = useState<string[]>([]);
  const [cloneSourceId, setCloneSourceId] = useState("");
  const [cloneName, setCloneName] = useState("");
  const [cloneDescription, setCloneDescription] = useState("");
  const [siteTemplateKey,setSiteTemplateKey]=useState("gastronomia-a");
  const [siteTenantId,setSiteTenantId]=useState("");
  const [capabilities,setCapabilities]=useState<string[]>([]);
  const [platformRole,setPlatformRole]=useState("");
  const [platformRoleLabel,setPlatformRoleLabel]=useState("Personal interno");
  const [staff,setStaff]=useState<PlatformStaff[]>([]);const [staffEmail,setStaffEmail]=useState("");const [staffRole,setStaffRole]=useState("designer");const [staffTenants,setStaffTenants]=useState<string[]>([]);

  async function load() {
    setLoading(true);
    try {
      const [companiesResponse, templatesResponse, sitesResponse,accessResponse,customizationsResponse] = await Promise.all([fetch("/api/admin/implementations", { cache:"no-store" }),fetch("/api/admin/templates", { cache:"no-store" }),fetch("/api/admin/sites",{cache:"no-store"}),fetch("/api/admin/access",{cache:"no-store"}),fetch("/api/admin/customizations",{cache:"no-store"})]);
      const [companiesData, templatesData, sitesData,accessData,customizationsData] = await Promise.all([companiesResponse.json(),templatesResponse.json(),sitesResponse.json(),accessResponse.json(),customizationsResponse.json()]);
      if (!companiesResponse.ok) throw new Error(companiesData.error || "No fue posible cargar las empresas.");
      if (!templatesResponse.ok) throw new Error(templatesData.error || "No fue posible cargar las plantillas.");
      setItems(companiesData); setTemplates(templatesData); setSites(sitesResponse.ok&&Array.isArray(sitesData)?sitesData:[]); setCustomizations(customizationsResponse.ok&&Array.isArray(customizationsData)?customizationsData:[]);
      setCapabilities(accessData.capabilities||[]); setPlatformRole(accessData.role||""); setPlatformRoleLabel(accessData.roleLabel||"Personal interno");
      if((accessData.capabilities||[]).includes("staff.manage")){const response=await fetch("/api/admin/staff",{cache:"no-store"});if(response.ok)setStaff(await response.json())}
      if(!sitesResponse.ok)setNotice({kind:"error",text:sitesData.error||"El constructor de sitios todavía no está habilitado en Supabase."});
      if (templatesData.length) { setTemplateId((current:string)=>current || templatesData[0].id); setModules((current:string[])=>current.length ? current : (templatesData[0].configuration?.modules || [])); }
    } catch (error) { setNotice({ kind:"error", text:error instanceof Error ? error.message : "No fue posible cargar." }); }
    finally { setLoading(false); }
  }

  useEffect(() => { void load(); }, []);
  const filtered = useMemo(() => items.filter(item => `${item.name} ${item.owner?.email || ""}`.toLowerCase().includes(query.toLowerCase())), [items, query]);
  const siteRubricTemplates = useMemo(() => siteTemplates.filter((template,index,array)=>array.findIndex(item=>item.businessType===template.businessType)===index), []);
  const siteBusinessLabels:Record<string,string>={gastronomy:"Restaurantes",real_estate:"Inmobiliarias",services:"Servicios",commerce:"Comercio",hospitality:"Hoteles y turismo"};

  function selectTemplate(id: string) { const selected=templates.find(item=>item.id===id); setTemplateId(id); setModules(selected?.configuration?.modules || []); }
  function toggleModule(key: string) { setModules(current => current.includes(key) ? current.filter(item => item !== key) : [...current, key]); }
  function closeForm() { setShowForm(false); setFormError(""); setName(""); setOwnerName(""); setOwnerEmail(""); if(templates[0])selectTemplate(templates[0].id); }

  async function createImplementation(event: FormEvent) {
    event.preventDefault();
    if(saving)return;
    setFormError(""); setNotice(null);
    if(name.trim().length<2){setFormError("Escribe el nombre de la empresa.");return}
    if(ownerName.trim().length<3){setFormError("Escribe el nombre completo del propietario.");return}
    if(!/^\S+@\S+\.\S+$/.test(ownerEmail.trim())){setFormError("Escribe un correo válido para el propietario.");return}
    if(!templateId){setFormError("Selecciona una plantilla.");return}
    if(!modules.length){setFormError("Activa al menos un módulo.");return}
    setSaving(true);
    try {
      const response = await fetch("/api/admin/implementations", { method:"POST", headers:{ "Content-Type":"application/json" }, body:JSON.stringify({ name, ownerName, ownerEmail, templateId, modules }) });
      const raw=await response.text();
      const data=raw?JSON.parse(raw):{};
      if (!response.ok) throw new Error(data.error || "No se pudo crear la implementación.");
      setItems(current => [data, ...current]); closeForm();
      setNotice({ kind:"success", text:`${data.name} fue creada y se envió la invitación a ${ownerEmail}.` });
    } catch (error) { setFormError(error instanceof Error ? error.message : "No se pudo crear la empresa ni enviar la invitación."); }
    finally { setSaving(false); }
  }

  async function changeStatus(tenantId: string, status: string) {
    if(statusSaving)return;
    const previous=items.find(item=>item.id===tenantId)?.implementation_status||"draft";
    let reason="";
    if(["suspended","archived"].includes(status)){reason=window.prompt(status==="suspended"?"Indica el motivo de la suspensión:":"Indica el motivo del archivo:")?.trim()||"";if(!reason){setNotice({kind:"error",text:"El cambio fue cancelado porque el motivo es obligatorio."});return;}}
    setStatusSaving(tenantId); setNotice(null);
    setItems(current=>current.map(item=>item.id===tenantId?{...item,implementation_status:status}:item));
    try{const response = await fetch("/api/admin/implementations", { method:"PATCH", headers:{ "Content-Type":"application/json" }, body:JSON.stringify({ tenantId, status, reason }) });const raw=await response.text();const data=raw?JSON.parse(raw):{};if (!response.ok) throw new Error(data.error||"No se pudo actualizar el estado.");setNotice({kind:"success",text:`Estado actualizado a ${statusLabels[status]}.`});}
    catch(error){setItems(current=>current.map(item=>item.id===tenantId?{...item,implementation_status:previous}:item));setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo actualizar el estado."})}
    finally{setStatusSaving(null)}
  }

  async function cloneTemplate(event:FormEvent){event.preventDefault();setSaving(true);setNotice(null);try{const response=await fetch("/api/admin/templates",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({sourceTenantId:cloneSourceId,name:cloneName,description:cloneDescription})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo crear la plantilla.");setTemplates(current=>[data,...current]);setShowCloneForm(false);setCloneSourceId("");setCloneName("");setCloneDescription("");setNotice({kind:"success",text:`La plantilla ${data.name} quedó lista para reutilizar.`});}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo clonar."});}finally{setSaving(false)}}
  async function archiveTemplate(id:string){if(!window.confirm("¿Archivar esta plantilla personalizada?"))return;const response=await fetch("/api/admin/templates",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,action:"archive"})});const data=await response.json();if(!response.ok){setNotice({kind:"error",text:data.error||"No se pudo archivar."});return}setTemplates(current=>current.filter(item=>item.id!==id));setNotice({kind:"success",text:"Plantilla archivada."})}
  function openTemplateEditor(template:ImplementationTemplate){setEditingTemplate(template);setEditorError("");const configuration=JSON.parse(JSON.stringify(template.configuration||{}));setEditorDraft({name:template.name,description:template.description,business_type:template.business_type,configuration});setEditorRaw({tenant_settings:JSON.stringify(configuration.tenant_settings||{},null,2),branding:JSON.stringify(configuration.branding||{},null,2),knowledge:JSON.stringify(configuration.knowledge||[],null,2),automations:JSON.stringify(configuration.automations||[],null,2),pipeline:JSON.stringify(configuration.pipeline||{},null,2),custom_fields:JSON.stringify(configuration.custom_fields||[],null,2),catalog:JSON.stringify(configuration.catalog||[],null,2),quick_replies:JSON.stringify(configuration.quick_replies||[],null,2),notifications:JSON.stringify(configuration.notifications||{},null,2)});void loadVersions(template.id)}
  async function loadVersions(id:string){const response=await fetch(`/api/admin/templates?templateId=${id}&versions=1`,{cache:"no-store"});if(response.ok)setVersions(await response.json())}
  function editorJson(key:"tenant_settings"|"branding"|"knowledge"|"automations"|"pipeline"|"custom_fields"|"catalog"|"quick_replies"|"notifications", fallback:unknown[]|Record<string,unknown>={}){return editorRaw[key] ?? JSON.stringify(editorDraft.configuration[key] ?? fallback,null,2)}
  function setEditorJson(key:"tenant_settings"|"branding"|"knowledge"|"automations"|"pipeline"|"custom_fields"|"catalog"|"quick_replies"|"notifications", value:string){setEditorRaw(current=>({...current,[key]:value}));try{const parsed=JSON.parse(value);setEditorError("");setEditorDraft(current=>({...current,configuration:{...current.configuration,[key]:parsed}}))}catch{setEditorError(`El bloque ${key} debe contener JSON válido.`)}}
  async function saveTemplateEditor(event:FormEvent){event.preventDefault();if(!editingTemplate||saving)return;if(editorError)return;setSaving(true);setNotice(null);try{const response=await fetch("/api/admin/templates",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editingTemplate.id,action:"update",name:editorDraft.name,description:editorDraft.description,business_type:editorDraft.business_type,configuration:editorDraft.configuration,changeSummary:"Edición desde el editor de plantillas"})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo guardar la plantilla.");setTemplates(current=>current.map(item=>item.id===data.id?data:item));setEditingTemplate(null);setNotice({kind:"success",text:`${data.name} guardada como versión ${data.current_version}.`})}catch(error){setEditorError(error instanceof Error?error.message:"No se pudo guardar la plantilla.")}finally{setSaving(false)}}
  async function restoreVersion(version:{id:string;version:number}){if(!editingTemplate||!window.confirm(`¿Restaurar la versión ${version.version}? Se creará una nueva versión con ese contenido.`))return;setSaving(true);try{const response=await fetch("/api/admin/templates",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:editingTemplate.id,action:"restore_version",versionId:version.id,versionNumber:version.version})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo restaurar.");setTemplates(current=>current.map(item=>item.id===data.id?data:item));setEditingTemplate(null);setNotice({kind:"success",text:`Se restauró la versión ${version.version}.`})}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo restaurar."})}finally{setSaving(false)}}
  function openApply(template:ImplementationTemplate){setApplyTemplate(template);setApplyTenantId("");setApplyReplace(false);setPreview(null);setNotice(null);setShowApplyForm(true)}
  async function previewTemplate(){if(!applyTemplate||!applyTenantId)return;setSaving(true);try{const response=await fetch("/api/admin/templates",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:applyTemplate.id,action:"preview",tenantId:applyTenantId})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo generar la vista previa.");setPreview(data)}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo generar la vista previa."})}finally{setSaving(false)}}
  async function applyTemplateToTenant(){if(!applyTemplate||!applyTenantId)return;if(!preview&&!window.confirm("¿Aplicar la plantilla? Se actualizarán configuraciones reutilizables, sin tocar datos privados."))return;setSaving(true);try{const response=await fetch("/api/admin/templates",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:applyTemplate.id,action:"apply",tenantId:applyTenantId,replace:applyReplace})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo aplicar la plantilla.");setShowApplyForm(false);setNotice({kind:"success",text:"Plantilla aplicada. Credenciales, usuarios, contactos y conversaciones quedaron intactos."})}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo aplicar la plantilla."})}finally{setSaving(false)}}
  async function checkMigrations(){setSaving(true);try{const response=await fetch("/api/admin/migrations",{cache:"no-store"});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo verificar Supabase.");const missing=(data.migrations||[]).filter((item:{applied:boolean})=>!item.applied);setNotice({kind:missing.length?"error":"success",text:missing.length?`Faltan migraciones en producción: ${missing.map((item:{migration:string})=>item.migration).join(", ")}.`:`Migraciones de plantillas, roles y auditoría confirmadas en producción (${new Date(data.checkedAt).toLocaleString("es-HN")}).`})}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo verificar migraciones."})}finally{setSaving(false)}}
  function openCustomizationForm(template:ImplementationTemplate, current?:Customization){const configuration=JSON.parse(JSON.stringify(current?.overrides||template.configuration||{}));setCustomizationTemplate(template);setCustomizationTenantId(current?.tenant_id||"");setCustomizationId(current?.id||null);setCustomizationDraft(configuration);setCustomizationRaw({configuration:JSON.stringify(configuration,null,2)});setCustomizationError("");setShowCustomizationForm(true)}
  function updateCustomizationJson(value:string){setCustomizationRaw({configuration:value});try{const parsed=JSON.parse(value);setCustomizationDraft(parsed);setCustomizationError("")}catch{setCustomizationError("La configuración debe contener JSON válido.")}}
  function reviewObject(value:unknown):Record<string,unknown>{return value&&typeof value==="object"&&!Array.isArray(value)?value as Record<string,unknown>:{} }
  function reviewArray(value:unknown):unknown[]{return Array.isArray(value)?value:[] }
  function reviewLabel(value:unknown,keys:string[],fallback:string){const object=reviewObject(value);for(const key of keys){if(typeof object[key]==="string"&&object[key])return object[key] as string}return fallback}
  function customizationReviewSections(item:Customization){
    const configuration=item.overrides||{};
    const assistant=reviewObject(configuration.assistant), pipeline=reviewObject(configuration.pipeline), branding=reviewObject(configuration.branding), tenantSettings=reviewObject(configuration.tenant_settings), notifications=reviewObject(configuration.notifications);
    const stages=reviewArray(pipeline.stages);
    return [
      {label:"Módulos habilitados",summary:`${reviewArray(configuration.modules).length}`,details:reviewArray(configuration.modules).map(String)},
      {label:"Asistente IA",summary:Object.keys(assistant).length?"Configurado":"Sin cambios",details:[assistant.assistant_name?`Nombre: ${String(assistant.assistant_name)}`:"",typeof assistant.instructions==="string"&&assistant.instructions?"Instrucciones configuradas":"",assistant.handoff_message?"Mensaje de transferencia configurado":""].filter(Boolean) as string[]},
      {label:"Documentos de conocimiento",summary:`${reviewArray(configuration.knowledge).length}`,details:reviewArray(configuration.knowledge).map((value,index)=>reviewLabel(value,["title","name","label"],`Documento ${index+1}`))},
      {label:"Automatizaciones",summary:`${reviewArray(configuration.automations).length}`,details:reviewArray(configuration.automations).map((value,index)=>reviewLabel(value,["name","title","label"],`Automatización ${index+1}`))},
      {label:"Pipeline y etapas",summary:`${stages.length} etapas`,details:stages.map((value,index)=>reviewLabel(value,["name","label","title"],`Etapa ${index+1}`))},
      {label:"Campos personalizados",summary:`${reviewArray(configuration.custom_fields).length}`,details:reviewArray(configuration.custom_fields).map((value,index)=>reviewLabel(value,["label","name","field_key"],`Campo ${index+1}`))},
      {label:"Catálogo, productos y servicios",summary:`${reviewArray(configuration.catalog).length}`,details:reviewArray(configuration.catalog).map((value,index)=>reviewLabel(value,["name","title","label"],`Elemento ${index+1}`))},
      {label:"Respuestas rápidas",summary:`${reviewArray(configuration.quick_replies).length}`,details:reviewArray(configuration.quick_replies).map((value,index)=>reviewLabel(value,["title","name","shortcut","label"],`Respuesta ${index+1}`))},
      {label:"Notificaciones",summary:Object.keys(notifications).length?"Configuradas":"Sin cambios",details:Object.keys(notifications)},
      {label:"Branding y widget",summary:Object.keys(branding).length||Object.keys(tenantSettings).length?"Configurado":"Sin cambios",details:[...Object.keys(branding).map(key=>`Branding: ${key}`),...Object.keys(tenantSettings).map(key=>`Widget/ajustes: ${key}`)]}
    ];
  }
  async function saveCustomization(submit:boolean){if(!customizationTemplate||!customizationTenantId||customizationError||saving)return;setSaving(true);setNotice(null);try{let id=customizationId||"";if(!id){const createdResponse=await fetch("/api/admin/customizations",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({tenantId:customizationTenantId,templateId:customizationTemplate.id})});const created=await createdResponse.json() as {id?:string;error?:string};if(!createdResponse.ok||!created.id)throw new Error(created.error||"No se pudo crear el borrador CRM.");id=created.id;setCustomizationId(id)}const updatedResponse=await fetch("/api/admin/customizations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id,action:submit?"submit":"update",overrides:customizationDraft})});const updated=await updatedResponse.json() as Customization & {error?:string};if(!updatedResponse.ok)throw new Error(updated.error||"No se pudo guardar la configuración CRM.");setCustomizations(current=>{const found=current.some(item=>item.id===updated.id);const enriched={...updated,tenant:{id:customizationTenantId,name:items.find(item=>item.id===customizationTenantId)?.name||"Empresa"},template:{id:customizationTemplate.id,name:customizationTemplate.name,current_version:customizationTemplate.current_version||1}};return found?current.map(item=>item.id===updated.id?{...item,...updated}:item):[enriched,...current]});setShowCustomizationForm(false);setNotice({kind:"success",text:submit?"Configuración CRM enviada a revisión.":"Borrador CRM guardado."})}catch(error){setCustomizationError(error instanceof Error?error.message:"No se pudo guardar la configuración CRM.")}finally{setSaving(false)}}
  async function reviewCustomization(item:Customization, action:"approve"|"reject"|"apply"){const reviewNote=action==="reject"?window.prompt("Indica qué debe corregir el vendedor:",item.review_note||"")?.trim()||"":"";if(action==="reject"&&!reviewNote){setNotice({kind:"error",text:"Escribe una observación para devolver la configuración CRM."});return}setSaving(true);try{const response=await fetch("/api/admin/customizations",{method:"PATCH",headers:{"Content-Type":"application/json"},body:JSON.stringify({id:item.id,action,reviewNote,replace:false})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo actualizar la revisión CRM.");setCustomizations(current=>current.map(value=>value.id===item.id?{...value,...data}:value));setReviewingCustomization(current=>current?.id===item.id?{...current,...data}:current);setNotice({kind:"success",text:action==="approve"?"Configuración CRM aprobada.":action==="apply"?"Configuración CRM aplicada a la empresa.":"Configuración CRM devuelta al vendedor."})}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo actualizar la configuración CRM."})}finally{setSaving(false)}}
  async function createSite(tenantId:string,templateKey=siteTemplateKey){setSaving(true);setNotice(null);try{const response=await fetch("/api/admin/sites",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({tenantId,templateKey})});const data=await response.json();if(!response.ok)throw new Error(data.error||"No se pudo preparar el sitio.");window.location.href=`/admin/sites/${data.id}`}catch(error){setNotice({kind:"error",text:error instanceof Error?error.message:"No se pudo preparar el sitio."});setSaving(false)}}
  function openSelectedSite(){if(!siteTenantId||!siteTemplateKey){setNotice({kind:"error",text:"Selecciona un rubro y una empresa asignada."});return}const existing=sites.find(site=>site.tenant_id===siteTenantId&&site.template_key===siteTemplateKey);if(existing){window.location.assign(`/admin/sites/${existing.id}`);return}void createSite(siteTenantId,siteTemplateKey)}
  async function inviteStaff(event:FormEvent){event.preventDefault();setSaving(true);const response=await fetch("/api/admin/staff",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({email:staffEmail,role:staffRole,tenantIds:staffTenants})});const data=await response.json();if(!response.ok){setNotice({kind:"error",text:data.error||"No se pudo invitar."});setSaving(false);return}setStaffEmail("");setStaffTenants([]);const refreshed=await fetch("/api/admin/staff",{cache:"no-store"});if(refreshed.ok)setStaff(await refreshed.json());setNotice({kind:"success",text:"Integrante invitado y permisos asignados."});setSaving(false)}
  async function logout(){if(loggingOut)return;setLoggingOut(true);const supabase=createClientSupabase();if(supabase)await supabase.auth.signOut({scope:"local"});window.location.replace("/login")}

  return <main className="superadmin-shell">
    <aside className="superadmin-sidebar">
      <div className="superadmin-brand"><span>G</span><div><strong>Gavrion</strong><small>Control de implementaciones</small></div></div>
      <nav>{capabilities.includes("companies.read")&&<button className={section==="companies"?"active":""} onClick={()=>setSection("companies")}>▦ Empresas</button>}{(capabilities.includes("customizations.write")||capabilities.includes("templates.write"))&&<button className={section==="customizations"?"active":""} onClick={()=>setSection("customizations")}>✎ Personalizaciones CRM</button>}{capabilities.includes("templates.read")&&<button className={section==="templates"?"active":""} onClick={()=>setSection("templates")}>◇ Plantillas</button>}{capabilities.includes("sites.read")&&<button className={section==="sites"?"active":""} onClick={()=>setSection("sites")}>▤ Sitios web</button>}{capabilities.includes("staff.manage")&&<button className={section==="team"?"active":""} onClick={()=>setSection("team")}>♙ Equipo interno</button>}</nav>
      <div className="superadmin-session"><div className="superadmin-identity"><span>{platformRoleLabel.slice(0,2).toUpperCase()}</span><div><strong>{platformRoleLabel}</strong><small>Acceso interno Gavrion</small></div></div><button className="superadmin-logout" disabled={loggingOut} onClick={()=>void logout()}><span>↪</span>{loggingOut?"Cerrando sesión…":"Cerrar sesión"}</button></div>
    </aside>
    <section className="superadmin-main">
      <header><div><p>PLATAFORMA GAVRION</p><h1>{section==="companies"?"Empresas asignadas":section==="templates"?"Plantillas de CRM":section==="customizations"?"Personalizaciones del CRM":"Editor de sitios"}</h1></div>{section==="companies"&&capabilities.includes("companies.create")&&<button className="admin-primary" onClick={()=>setShowForm(true)}>＋ Nueva implementación</button>}{section==="templates"&&<div className="admin-header-actions"><button className="admin-secondary" disabled={saving} onClick={()=>void checkMigrations()}>Verificar Supabase</button>{capabilities.includes("templates.write")&&<button className="admin-primary" onClick={()=>setShowCloneForm(true)}>＋ Crear desde una empresa</button>}</div>}{section==="customizations"&&capabilities.includes("customizations.write")&&<button className="admin-primary" onClick={()=>setSection("templates")}>Elegir plantilla CRM</button>}</header>
      <div className="superadmin-content">
        {section==="customizations"&&<section className="templates-library"><div className="templates-intro"><div><h2>Personalizaciones del CRM en curso</h2><p>El vendedor adapta una copia de la configuración del CRM. Solo una revisión aprobada puede aplicarse a la empresa.</p></div><span>{customizations.length} empresas</span></div><div className="customization-list">{customizations.length?customizations.map(item=><article key={item.id}><div><strong>{item.tenant?.name||"Empresa"}</strong><small>{item.template?.name||"Plantilla CRM"} · versión {item.template_version}</small></div><span className={`customization-status ${item.status}`}>{({draft:"Borrador",review:"En revisión",approved:"Aprobada",applied:"Aplicada",rejected:"Devuelta"} as Record<string,string>)[item.status]}</span><div className="customization-actions"><button className="admin-secondary" onClick={()=>setReviewingCustomization(item)}>Ver cambios</button>{["draft","rejected"].includes(item.status)&&<button className="admin-secondary" onClick={()=>{const template=templates.find(value=>value.id===item.template_id);if(template)openCustomizationForm(template,item)}}>Editar</button>}{item.status==="review"&&capabilities.includes("templates.write")&&<><button className="admin-secondary" disabled={saving} onClick={()=>void reviewCustomization(item,"reject")}>Devolver</button><button className="admin-primary" disabled={saving} onClick={()=>void reviewCustomization(item,"approve")}>Aprobar</button></>}{item.status==="approved"&&capabilities.includes("templates.write")&&<button className="admin-primary" disabled={saving} onClick={()=>void reviewCustomization(item,"apply")}>Aplicar al CRM</button>}</div></article>):<div className="admin-empty">Todavía no hay personalizaciones del CRM. Pulsa “Elegir plantilla CRM” para comenzar.</div>}</div></section>}
        {section==="templates"&&capabilities.includes("customizations.write")&&<button className="admin-primary customization-launch" onClick={()=>templates[0]&&openCustomizationForm(templates[0])}>＋ Personalizar para una empresa</button>}
        {notice&&<div className={`admin-notice ${notice.kind}`}>{notice.text}<button onClick={()=>setNotice(null)}>×</button></div>}
        {section==="companies"&&<><section className="admin-stats">
          <article><span>Empresas</span><strong>{items.length}</strong><small>Total registradas</small></article>
          <article><span>En preparación</span><strong>{items.filter(item=>["draft","configuring","testing"].includes(item.implementation_status)).length}</strong><small>Pendientes de entrega</small></article>
          <article><span>En producción</span><strong>{items.filter(item=>item.implementation_status==="production").length}</strong><small>Clientes activos</small></article>
        </section>
        <section className="admin-panel">
          <div className="admin-panel-head"><div><h2>Empresas</h2><p>Construye, prueba y entrega cada CRM desde un solo lugar.</p></div><label>⌕ <input value={query} onChange={event=>setQuery(event.target.value)} placeholder="Buscar empresa o propietario" /></label></div>
          <div className="admin-table-wrap"><table><thead><tr><th>Empresa</th><th>Plantilla</th><th>Propietario</th><th>Módulos</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>
            {loading?<tr><td colSpan={6} className="admin-empty">Cargando implementaciones…</td></tr>:filtered.length?filtered.map(item=><tr key={item.id}>
              <td><strong>{item.name}</strong><small>{item.slug}</small></td>
              <td>{templates.find(option=>option.id===item.implementation_template_id)?.name || item.template_key}</td>
              <td><strong>{item.owner?.name || "Sin propietario"}</strong><small>{item.owner?.email || "—"}</small></td>
              <td><span className="module-count">{item.settings?.modules?.length || 0} activos</span></td>
              <td><select disabled={!capabilities.includes("companies.create")||statusSaving===item.id} title={capabilities.includes("companies.create")?"Actualizar estado":"El estado lo actualiza el implementador o superadmin"} value={item.implementation_status} onChange={event=>void changeStatus(item.id,event.target.value)}><option value="draft">Borrador</option><option value="configuring">Configuración</option><option value="testing">Pruebas</option><option value="ready">Lista para entregar</option><option value="production">Producción</option><option value="suspended">Suspendida</option><option value="archived">Archivada</option></select>{statusSaving===item.id&&<small className="status-progress">Guardando…</small>}<small className={`implementation-status status-${item.implementation_status}`}>{statusLabels[item.implementation_status]}</small></td>
              <td>{capabilities.includes("support.open")?<a className="support-button" title="Abrir el CRM de esta empresa en modo soporte" href={`/dashboard?supportTenant=${item.id}`} target="_blank" rel="noreferrer">Abrir en soporte ↗</a>:<span>—</span>}</td>
            </tr>):<tr><td colSpan={6} className="admin-empty">No hay empresas que coincidan.</td></tr>}
          </tbody></table></div>
        </section></>}
        {section==="templates"&&<section className="templates-library"><div className="templates-intro"><div><h2>Biblioteca de plantillas</h2><p>Edita instrucciones, automatizaciones y módulos. Aplica una plantilla a empresas existentes con vista previa y conserva un historial restaurable.</p></div><span>{templates.length} disponibles</span></div><div className="template-library-grid">{templates.map(template=><article key={template.id}><div className="template-card-top"><span>{template.business_type.slice(0,2).toUpperCase()}</span>{template.is_system&&<i>Base Gavrion</i>}</div><h3>{template.name}</h3><p>{template.description||"Plantilla personalizada creada desde una implementación."}</p><div className="template-summary"><span>{template.configuration.modules?.length||0} módulos</span><span>{template.configuration.knowledge?.length||0} documentos</span><span>{template.configuration.automations?.length||0} flujos</span><span>v{template.current_version||1}</span></div><div className="template-card-actions">{capabilities.includes("companies.create")&&<button onClick={()=>{selectTemplate(template.id);setSection("companies");setShowForm(true)}}>Usar al crear</button>}{capabilities.includes("customizations.write")&&<button onClick={()=>openCustomizationForm(template)}>Personalizar</button>}{capabilities.includes("templates.write")&&<><button onClick={()=>openApply(template)}>Aplicar</button><button onClick={()=>openTemplateEditor(template)}>Editar / historial</button>{!template.is_system&&<button className="archive-template" onClick={()=>void archiveTemplate(template.id)}>Archivar</button>}</>}</div></article>)}</div></section>}
        {false&&section==="sites"&&<section className="templates-library"><div className="templates-intro"><div><h2>Catálogo de sitios</h2><p>Selecciona un modelo y crea una implementación independiente usando el mismo editor, vista previa y publicación.</p></div><span>{sites.length} proyectos</span></div><div className="site-template-picker">{siteTemplates.map(template=><button key={template.key} className={siteTemplateKey===template.key?"selected":""} onClick={()=>setSiteTemplateKey(template.key)}><strong>{template.name}</strong><small>{template.description}</small></button>)}</div><div className="site-project-grid">{items.map(company=>{const site=sites.find(item=>item.tenant_id===company.id&&item.template_key===siteTemplateKey),template=siteTemplates.find(item=>item.key===siteTemplateKey)!;return <article key={company.id}><div className="site-project-preview"><span>{template.name.toUpperCase()}</span><strong>{site?.name||company.name}</strong></div><div><h3>{company.name}</h3><p>{site?`Última edición: ${new Date(site.updated_at).toLocaleDateString("es-HN")}`:`Todavía no utiliza ${template.name}.`}</p><span className={`site-status ${site?.status||"new"}`}>{site?({draft:"Borrador",review:"En revisión",ready:"Listo",exported:"Exportado"} as Record<string,string>)[site.status]||site.status:"Nuevo"}</span><button disabled={saving} onClick={()=>site?window.location.assign(`/admin/sites/${site.id}`):void createSite(company.id,template.key)}>{site?"Abrir editor":`Crear con ${template.name}`}</button></div></article>})}</div></section>}
        {section==="sites"&&<section className="templates-library"><div className="templates-intro"><div><h2>Plantillas de sitios por rubro</h2><p>Selecciona una plantilla única del rubro y asígnala a una empresa que tengas autorizada. Cada trabajo queda registrado para continuar, revisar o entregar.</p></div><span>{sites.length} trabajos</span></div><div className="site-assignment-panel"><div className="site-flow-step"><span>1</span><div><strong>Selecciona el rubro</strong><small>Por ahora se trabaja una plantilla base por cada tipo de negocio.</small></div></div><div className="site-rubric-grid">{siteRubricTemplates.map(template=><button key={template.key} className={siteTemplateKey===template.key?"selected":""} onClick={()=>setSiteTemplateKey(template.key)}><span>{siteBusinessLabels[template.businessType]||template.businessType}</span><strong>{template.name}</strong><small>{template.description}</small></button>)}</div><div className="site-flow-step"><span>2</span><div><strong>Selecciona la empresa asignada</strong><small>Solo aparecen empresas autorizadas para tu usuario.</small></div></div><div className="site-assignment-controls"><select value={siteTenantId} onChange={event=>setSiteTenantId(event.target.value)}><option value="">Selecciona una empresa</option>{items.map(company=><option value={company.id} key={company.id}>{company.name}</option>)}</select><button className="admin-primary" disabled={saving||!siteTenantId||!capabilities.includes("sites.write")} onClick={openSelectedSite}>{sites.some(site=>site.tenant_id===siteTenantId&&site.template_key===siteTemplateKey)?"Continuar editando":"Crear sitio para esta empresa"}</button></div><div className="site-assignment-summary"><strong>{siteTemplates.find(template=>template.key===siteTemplateKey)?.name}</strong><span>→</span><strong>{items.find(company=>company.id===siteTenantId)?.name||"Empresa pendiente"}</strong></div></div><div className="site-history-head"><div><h2>Historial de sitios trabajados</h2><p>Consulta qué plantilla está vinculada a cada empresa, su estado y la última edición.</p></div><span>{sites.length} registrados</span></div><div className="site-history-list">{sites.length?sites.map(site=>{const template=siteTemplates.find(value=>value.key===site.template_key);const company=site.tenant?.name||items.find(value=>value.id===site.tenant_id)?.name||"Empresa";return <article key={site.id}><div className="site-history-icon">{(siteBusinessLabels[template?.businessType||""]||"Sitio").slice(0,2).toUpperCase()}</div><div className="site-history-main"><strong>{company}</strong><small>{template?.name||`Plantilla archivada · ${site.template_key}`}</small><span>Última edición: {new Date(site.updated_at).toLocaleString("es-HN")}</span></div><span className={`site-status ${site.status}`}>{({draft:"Borrador",review:"En revisión",ready:"Listo para publicar",exported:"Exportado"} as Record<string,string>)[site.status]||site.status}</span>{site.status==="review"&&["superadmin","implementer"].includes(platformRole)&&<button className="admin-primary" onClick={()=>window.location.assign(`/admin/sites/${site.id}/review`)}>Revisar sitio</button>}<button className="admin-secondary" disabled={!capabilities.includes("sites.write")} onClick={()=>window.location.assign(`/admin/sites/${site.id}`)}>Abrir editor</button></article>}) : <div className="admin-empty">Aún no hay sitios trabajados. Selecciona un rubro y una empresa para comenzar.</div>}</div></section>}
        {section==="team"&&<section className="admin-panel internal-team"><div className="admin-panel-head"><div><h2>Equipo interno Gavrion</h2><p>Asigna una función y limita a cada persona a las empresas que debe operar.</p></div></div><form onSubmit={inviteStaff}><label>Correo<input type="email" required value={staffEmail} onChange={e=>setStaffEmail(e.target.value)} placeholder="persona@gavrionsystems.com"/></label><label>Rol<select value={staffRole} onChange={e=>setStaffRole(e.target.value)}><option value="designer">Diseñador</option><option value="sales">Vendedor</option><option value="implementer">Implementador</option><option value="support">Soporte</option></select></label><fieldset><legend>Empresas asignadas</legend>{items.map(company=><label key={company.id}><input type="checkbox" checked={staffTenants.includes(company.id)} onChange={e=>setStaffTenants(current=>e.target.checked?[...current,company.id]:current.filter(id=>id!==company.id))}/>{company.name}</label>)}</fieldset><button className="admin-primary" disabled={saving}>{saving?"Guardando…":"Invitar y asignar"}</button></form><div className="staff-list">{staff.map(person=><article key={person.user_id}><div><strong>{person.email||"Usuario"}</strong><small>{({superadmin:"Superadministrador",designer:"Diseñador",sales:"Vendedor",implementer:"Implementador",support:"Soporte"} as Record<string,string>)[person.role]}</small></div><span>{person.role==="superadmin"?"Todas las empresas":`${person.tenant_ids.length} empresas`}</span><i className={person.active?"active":""}>{person.active?"Activo":"Desactivado"}</i></article>)}</div></section>}
      </div>
    </section>
        {reviewingCustomization&&<div className="implementation-modal" role="dialog" aria-modal="true"><section className="review-customization-modal"><div className="modal-title"><div><p>REVISIÓN DE CONFIGURACIÓN CRM</p><h2>{reviewingCustomization.tenant?.name||"Empresa"}</h2><small>{reviewingCustomization.template?.name||"Plantilla CRM"} · versión {reviewingCustomization.template_version}</small></div><button type="button" onClick={()=>setReviewingCustomization(null)}>×</button></div><p className="clone-help">Vista de solo lectura de lo que preparó el vendedor. Revisa cada bloque antes de aprobar; nada se aplica a la empresa hasta que lo autorices.</p><div className="review-summary-grid">{customizationReviewSections(reviewingCustomization).map(section=><article key={section.label}><div><strong>{section.label}</strong><span>{section.summary}</span></div>{section.details.length?<ul>{section.details.map(detail=><li key={detail}>{detail}</li>)}</ul>:<small>Sin elementos declarados.</small>}</article>)}</div><details className="review-json"><summary>Ver configuración segura completa</summary><pre>{JSON.stringify(reviewingCustomization.overrides||{},null,2)}</pre></details>{reviewingCustomization.review_note&&<div className="review-note"><strong>Observaciones anteriores</strong><p>{reviewingCustomization.review_note}</p></div>}<div className="admin-modal-actions">{reviewingCustomization.status==="review"&&capabilities.includes("templates.write")&&<><button type="button" className="admin-secondary" disabled={saving} onClick={()=>void reviewCustomization(reviewingCustomization,"reject")}>Devolver con observaciones</button><button type="button" className="admin-primary" disabled={saving} onClick={()=>void reviewCustomization(reviewingCustomization,"approve")}>Aprobar configuración CRM</button></>}{reviewingCustomization.status==="approved"&&capabilities.includes("templates.write")&&<button type="button" className="admin-primary" disabled={saving} onClick={()=>void reviewCustomization(reviewingCustomization,"apply")}>Aplicar al CRM</button>}<button type="button" className="admin-secondary" onClick={()=>setReviewingCustomization(null)}>Cerrar</button></div></section></div>}
        {showForm&&<div className="implementation-modal" role="dialog" aria-modal="true"><form onSubmit={createImplementation} noValidate>
      <div className="modal-title"><div><p>NUEVO CLIENTE</p><h2>Nueva implementación</h2></div><button type="button" onClick={closeForm}>×</button></div>
      <div className="admin-form-grid"><label>Nombre de la empresa<input required minLength={2} value={name} onChange={event=>setName(event.target.value)} placeholder="Ej. Metro Inmobiliaria" /></label><label>Nombre del propietario<input required minLength={3} value={ownerName} onChange={event=>setOwnerName(event.target.value)} placeholder="Nombre completo" /></label><label className="wide">Correo del propietario<input required type="email" value={ownerEmail} onChange={event=>setOwnerEmail(event.target.value)} placeholder="propietario@empresa.com" /><small>Recibirá una invitación para establecer su acceso.</small></label></div>
      <fieldset><legend>Selecciona una plantilla</legend><div className="template-grid">{templates.map(option=><button type="button" key={option.id} className={templateId===option.id?"selected":""} onClick={()=>selectTemplate(option.id)}><strong>{option.name}</strong><small>{option.description}</small></button>)}</div></fieldset>
      <fieldset><legend>Activa los módulos</legend><div className="module-grid">{moduleOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={modules.includes(key)} onChange={()=>toggleModule(key)} /><span>{label}</span></label>)}</div></fieldset>
      {formError&&<div className="implementation-form-error" role="alert"><strong>No se pudo completar la implementación</strong><span>{formError}</span>{/rate|limit|email|correo|mail/i.test(formError)&&<small>Si Supabase limitó los correos, espera antes de volver a intentarlo o configura un servidor SMTP propio.</small>}</div>}
      <div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={closeForm}>Cancelar</button><button disabled={saving} className="admin-primary">{saving?"Creando…":"Crear e invitar propietario"}</button></div>
    </form></div>}
    {showCloneForm&&<div className="implementation-modal" role="dialog" aria-modal="true"><form onSubmit={cloneTemplate} className="clone-template-form"><div className="modal-title"><div><p>CLONADOR</p><h2>Crear plantilla desde una empresa</h2></div><button type="button" onClick={()=>setShowCloneForm(false)}>×</button></div><p className="clone-help">Se copiarán únicamente configuraciones reutilizables. No se copiarán contactos, conversaciones, credenciales, usuarios, propiedades, pedidos ni datos legales.</p><div className="admin-form-grid"><label className="wide">Empresa de origen<select required value={cloneSourceId} onChange={event=>setCloneSourceId(event.target.value)}><option value="">Selecciona una empresa configurada</option>{items.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label>Nombre de la plantilla<input required minLength={3} value={cloneName} onChange={event=>setCloneName(event.target.value)} placeholder="Ej. Inmobiliaria premium" /></label><label>Descripción<input value={cloneDescription} onChange={event=>setCloneDescription(event.target.value)} placeholder="Qué incluye y cuándo utilizarla" /></label></div><div className="clone-includes"><strong>Se incluye</strong><span>✓ Módulos activados</span><span>✓ Instrucciones de IA</span><span>✓ Base de conocimiento</span><span>✓ Automatizaciones</span><span>✓ Widget y horarios</span><span>✓ Pipeline, campos y catálogo</span></div><div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={()=>setShowCloneForm(false)}>Cancelar</button><button disabled={saving} className="admin-primary">{saving?"Clonando…":"Guardar como plantilla"}</button></div></form></div>}
    {editingTemplate&&<div className="implementation-modal" role="dialog" aria-modal="true"><form onSubmit={saveTemplateEditor} className="template-editor-form"><div className="modal-title"><div><p>EDITOR DE PLANTILLAS · v{editingTemplate.current_version||1}</p><h2>{editingTemplate.name}</h2></div><button type="button" onClick={()=>setEditingTemplate(null)}>×</button></div><p className="clone-help">Los cambios crean una nueva versión. Los tokens, credenciales, usuarios, contactos, conversaciones y valores de campos nunca forman parte de una plantilla.</p><div className="admin-form-grid"><label>Nombre<input required value={editorDraft.name} onChange={e=>setEditorDraft(d=>({...d,name:e.target.value}))}/></label><label>Tipo de negocio<select value={editorDraft.business_type} onChange={e=>setEditorDraft(d=>({...d,business_type:e.target.value}))}><option value="generic">General</option><option value="real_estate">Inmobiliaria</option><option value="restaurant">Restaurante</option><option value="services">Servicios</option><option value="commerce">Comercio</option></select></label><label className="wide">Descripción<input value={editorDraft.description} onChange={e=>setEditorDraft(d=>({...d,description:e.target.value}))}/></label></div><fieldset><legend>Módulos reutilizables</legend><div className="module-grid">{moduleOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={(editorDraft.configuration.modules||[]).includes(key)} onChange={()=>setEditorDraft(d=>({...d,configuration:{...d.configuration,modules:(d.configuration.modules||[]).includes(key)?(d.configuration.modules||[]).filter(item=>item!==key):[...(d.configuration.modules||[]),key]}}))}/><span>{label}</span></label>)}</div></fieldset><section className="editor-section"><h3>Asistente IA</h3><div className="admin-form-grid"><label>Nombre<input value={String(editorDraft.configuration.assistant?.assistant_name||"")} onChange={e=>setEditorDraft(d=>({...d,configuration:{...d.configuration,assistant:{...(d.configuration.assistant||{}),assistant_name:e.target.value}}}))}/></label><label className="wide">Instrucciones<textarea rows={4} value={String(editorDraft.configuration.assistant?.instructions||"")} onChange={e=>setEditorDraft(d=>({...d,configuration:{...d.configuration,assistant:{...(d.configuration.assistant||{}),instructions:e.target.value}}}))}/></label><label className="wide">Mensaje de transferencia<textarea rows={2} value={String(editorDraft.configuration.assistant?.handoff_message||"")} onChange={e=>setEditorDraft(d=>({...d,configuration:{...d.configuration,assistant:{...(d.configuration.assistant||{}),handoff_message:e.target.value}}}))}/></label></div></section><div className="editor-json-grid"><label>Widget, branding y notificaciones (JSON)<textarea rows={6} value={editorJson("tenant_settings",{})} onChange={e=>setEditorJson("tenant_settings",e.target.value)}/></label><label>Documentos de conocimiento (JSON)<textarea rows={7} value={editorJson("knowledge",[])} onChange={e=>setEditorJson("knowledge",e.target.value)}/></label><label>Automatizaciones (JSON)<textarea rows={7} value={editorJson("automations",[])} onChange={e=>setEditorJson("automations",e.target.value)}/></label><label>Pipeline y etapas (JSON)<textarea rows={6} value={editorJson("pipeline",{})} onChange={e=>setEditorJson("pipeline",e.target.value)}/></label><label>Campos personalizados (JSON)<textarea rows={6} value={editorJson("custom_fields",[])} onChange={e=>setEditorJson("custom_fields",e.target.value)}/></label><label>Catálogo / productos / servicios (JSON)<textarea rows={6} value={editorJson("catalog",[])} onChange={e=>setEditorJson("catalog",e.target.value)}/></label></div>{editorError&&<div className="implementation-form-error"><strong>Revisa el editor</strong><span>{editorError}</span></div>}<div className="version-history"><h3>Historial y rollback</h3>{versions.map(version=><div key={version.id}><span><strong>v{version.version}</strong> · {version.change_summary||"Edición"}<small>{new Date(version.created_at).toLocaleString("es-HN")}</small></span><button type="button" className="admin-secondary" disabled={saving||version.version===(editingTemplate.current_version||1)} onClick={()=>void restoreVersion(version)}>Restaurar</button></div>)}</div><div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={()=>setEditingTemplate(null)}>Cancelar</button><button disabled={saving||Boolean(editorError)} className="admin-primary">{saving?"Guardando…":"Guardar nueva versión"}</button></div></form></div>}
    {showApplyForm&&applyTemplate&&<div className="implementation-modal" role="dialog" aria-modal="true"><form onSubmit={e=>{e.preventDefault();void applyTemplateToTenant()}} className="apply-template-form"><div className="modal-title"><div><p>APLICAR PLANTILLA · v{applyTemplate.current_version||1}</p><h2>{applyTemplate.name}</h2></div><button type="button" onClick={()=>setShowApplyForm(false)}>×</button></div><p className="clone-help">Actualiza una empresa existente sin eliminar información privada. Puedes añadir lo nuevo o reemplazar únicamente documentos y automatizaciones.</p><label className="apply-company-label">Empresa destino<select required value={applyTenantId} onChange={e=>{setApplyTenantId(e.target.value);setPreview(null)}}><option value="">Selecciona una empresa</option>{items.map(item=><option value={item.id} key={item.id}>{item.name}</option>)}</select></label><label className="replace-option"><input type="checkbox" checked={applyReplace} onChange={e=>setApplyReplace(e.target.checked)}/> Reemplazar documentos y automatizaciones existentes (no borra contactos, conversaciones ni credenciales)</label><button type="button" className="admin-secondary" disabled={!applyTenantId||saving} onClick={()=>void previewTemplate()}>▣ Generar vista previa y diferencias</button>{preview&&<div className="template-preview"><strong>Se aplicará a {items.find(item=>item.id===applyTenantId)?.name}</strong>{preview.sections.map(section=><div key={section.label}><span>{section.label}</span><span>{section.current} actuales → {section.incoming} de plantilla {section.changed?"· cambia":"· sin cambios"}</span></div>)}<small>{preview.warning}</small></div>}<div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={()=>setShowApplyForm(false)}>Cancelar</button><button disabled={saving||!applyTenantId} className="admin-primary">{saving?"Aplicando…":"Aplicar a la empresa"}</button></div></form></div>}
    {showCustomizationForm&&<div className="implementation-modal" role="dialog" aria-modal="true"><form onSubmit={e=>{e.preventDefault();void saveCustomization(false)}} className="customization-form"><div className="modal-title"><div><p>PERSONALIZACIÓN DEL CRM</p><h2>{customizationId?"Editar borrador CRM":"Nueva personalización CRM"}</h2></div><button type="button" onClick={()=>setShowCustomizationForm(false)}>×</button></div><p className="clone-help">Esta copia de la configuración CRM es exclusiva para la empresa seleccionada. La plantilla global permanece intacta.</p><div className="admin-form-grid"><label className="wide">Plantilla CRM de origen<select required value={customizationTemplate?.id||""} onChange={e=>{const template=templates.find(item=>item.id===e.target.value);if(template&&!customizationId)openCustomizationForm(template)}} disabled={Boolean(customizationId)}><option value="">Selecciona una plantilla CRM</option>{templates.map(item=><option key={item.id} value={item.id}>{item.name} · v{item.current_version||1}</option>)}</select></label><label className="wide">Empresa/prospecto<select required value={customizationTenantId} onChange={e=>setCustomizationTenantId(e.target.value)} disabled={Boolean(customizationId)}><option value="">Selecciona una empresa asignada</option>{items.map(item=><option key={item.id} value={item.id}>{item.name}</option>)}</select></label></div><fieldset><legend>Módulos del CRM habilitados</legend><div className="module-grid">{moduleOptions.map(([key,label])=><label key={key}><input type="checkbox" checked={(customizationDraft.modules||[]).includes(key)} onChange={()=>setCustomizationDraft(current=>({...current,modules:(current.modules||[]).includes(key)?(current.modules||[]).filter(item=>item!==key):[...(current.modules||[]),key]}))}/><span>{label}</span></label>)}</div></fieldset><label className="customization-instructions">Instrucciones de IA<textarea rows={4} value={String(customizationDraft.assistant?.instructions||"")} onChange={e=>setCustomizationDraft(current=>({...current,assistant:{...(current.assistant||{}),instructions:e.target.value}}))}/></label><label className="customization-instructions">Configuración segura del CRM (branding, widget, respuestas rápidas, notificaciones, pipeline, campos y catálogo) · JSON<textarea rows={10} value={customizationRaw.configuration||JSON.stringify(customizationDraft,null,2)} onChange={e=>updateCustomizationJson(e.target.value)}/></label>{customizationError&&<div className="implementation-form-error"><strong>Revisa la configuración del CRM</strong><span>{customizationError}</span></div>}<div className="admin-modal-actions"><button type="button" className="admin-secondary" onClick={()=>setShowCustomizationForm(false)}>Cancelar</button><button type="button" className="admin-secondary" disabled={saving||Boolean(customizationError)||!customizationTenantId} onClick={()=>void saveCustomization(false)}>Guardar borrador CRM</button><button type="button" className="admin-primary" disabled={saving||Boolean(customizationError)||!customizationTenantId} onClick={()=>void saveCustomization(true)}>Enviar configuración CRM a revisión</button></div></form></div>}
  </main>;
}
